; apx_promoted.asm -- APX EVEX promotion of legacy maps 2/3 (Phase 4b)
;
; Environment
;	Assembly-time only: nothing here is executed (no APX processor is public
;	yet). fasmg assembles each instruction inside VIRTUAL and compares the
;	bytes (reference: llvm-mc 23, generated by tests/iset/_apx_diff.py; the
;	same instructions pass LLVM's adx, cet, crc32, enqcmd, invpcid, movbe,
;	movdir64b, movdiri, rao-int, user-msr and vmx Intel-syntax tests through
;	tests/iset/_apx_corpus.py); a mismatch stops assembly with 'encoding
;	mismatch'. The failure cases at the end are each assembled alone by
;	_run.ps1 (-i"FAIL=n") and must stop with the quoted message.
;	By hand:  fasm2 apx_promoted.asm apx_promoted.bin
;
; What is new (spec 355828 3.1.2.3.1 rule 2e)
;	Legacy maps 2 and 3 have no REX2. Their general-purpose instructions are
;	promoted to EVEX map 4, so with r16-r31 (or {evex}, when APX_F is on)
;	x86.store_instruction writes EVEX instead of refusing; no instruction
;	definition changed for it. Map 4 opcodes and pp (as llvm-mc):
;	movbe F0/F1 -> 60/61; crc32 F0/F1 (F2 dropped, pp=66 for 16-bit);
;	invept/invvpid/invpcid 80-82 -> F0-F2 with pp=F3; wruss F5 -> 65;
;	adcx/adox/wrss F6 -> 66; movdir64b/enqcmd(s)/urdmsr/uwrmsr F8,
;	movdiri F9, aadd/aand/aor/axor FC keep opcode and prefix (as pp).
;	Also: movbe r, r (new in APX, EVEX only, F1 direction); adcx/adox NDD
;	(layers); urdmsr/uwrmsr imm32 in EVEX map 7. SSE, AES and SHA in map 2/3
;	are not promoted: r16-r31 are refused there (apx_rex2.asm), {evex} is
;	ignored. Failure modes this file guards against:
;	- {evex} (also a global "use evex" for AVX-512 code) must not touch
;	  legacy instructions when APX_F is off;
;	- the legacy forms keep their bytes.
;
; FAIL 1: 'APX_F or higher required'
; FAIL 2: 'APX_F or higher required'
; FAIL 3: 'APX_F or higher required'
; FAIL 4: 'bits64 or higher required'
; FAIL 5: '{nf} not supported by this instruction'
; FAIL 6: 'invalid combination of operands'

macro expect bytes*, line&
	local n, got, k, want
	virtual at 0
		line
		n = $
		load got:n from 0
	end virtual
	virtual at 0
		db bytes
		k = $
		load want:k from 0
	end virtual
	if n <> k | got <> want
		display 'FAIL: ', `line, 13, 10
		err 'encoding mismatch'
	end if
end macro

use64

if ~ defined FAIL

	use everything
	expect <48h,0Fh,38h,0F0h,03h>, movbe rax, [rbx]
	expect <0Fh,38h,0F1h,0Bh>, movbe [rbx], ecx
	expect <62h,0F4h,0FCh,08h,61h,0D8h>, movbe rax, rbx
	expect <62h,0F4h,7Ch,08h,61h,0D8h>, movbe eax, ebx
	expect <62h,0F4h,7Dh,08h,61h,0D8h>, movbe ax, bx
	expect <62h,0ECh,0FCh,08h,61h,0C8h>, movbe r16, r17
	expect <62h,0ECh,0FCh,08h,60h,01h>, movbe r16, [r17]
	expect <62h,0ECh,79h,08h,61h,34h,6Ch>, movbe [r20+r21*2], r22w
	expect <62h,0F4h,0FCh,08h,60h,03h>, {evex} movbe rax, [rbx]
	expect <0F2h,0Fh,38h,0F0h,0C3h>, crc32 eax, bl
	expect <0F2h,48h,0Fh,38h,0F0h,0D8h>, crc32 rbx, al
	expect <66h,0F2h,0Fh,38h,0F1h,0C3h>, crc32 eax, bx
	expect <62h,0E4h,7Ch,08h,0F0h,0C0h>, crc32 r16d, al
	expect <62h,0FCh,7Ch,08h,0F0h,0C0h>, crc32 eax, r16b
	expect <62h,0ECh,0FCh,08h,0F1h,01h>, crc32 r16, qword [r17]
	expect <62h,8Ch,0F8h,08h,0F0h,9Ch,0ACh,23h,01h,00h,00h>, crc32 r19, byte [r28+4*r29+291]
	expect <62h,0F4h,7Ch,08h,0F0h,0C3h>, {evex} crc32 eax, bl
	expect <62h,0F4h,0FCh,08h,0F0h,0D8h>, {evex} crc32 rbx, al
	expect <66h,48h,0Fh,38h,0F6h,0C3h>, adcx rax, rbx
	expect <0F3h,0Fh,38h,0F6h,03h>, adox eax, [rbx]
	expect <62h,0ECh,0FDh,08h,66h,0C1h>, adcx r16, r17
	expect <62h,0F4h,0F5h,18h,66h,0C3h>, adcx rcx, rax, rbx
	expect <62h,0F4h,0F5h,18h,66h,03h>, adcx rcx, rax, [rbx]
	expect <62h,0F4h,76h,18h,66h,0C3h>, adox ecx, eax, ebx
	expect <62h,0ECh,0DEh,10h,66h,2Eh>, adox r20, r21, [r22]
	expect <62h,0F4h,0FDh,08h,66h,0C3h>, {evex} adcx rax, rbx
	expect <62h,0F4h,0FEh,08h,66h,0C3h>, {evex} adox rax, rbx
	expect <62h,0E4h,7Eh,08h,0F0h,00h>, invept r16, [rax]
	expect <62h,0FCh,7Eh,08h,0F1h,00h>, invvpid rax, [r16]
	expect <62h,0E4h,7Eh,08h,0F2h,00h>, invpcid r16, [rax]
	expect <62h,0F4h,7Eh,08h,0F2h,03h>, {evex} invpcid rax, [rbx]
	expect <62h,0FCh,0FCh,08h,66h,00h>, wrssq [r16], rax
	expect <62h,0E4h,7Ch,08h,66h,00h>, wrssd [rax], r16d
	expect <62h,0FCh,0FDh,08h,65h,00h>, wrussq [r16], rax
	expect <62h,0E4h,7Dh,08h,65h,00h>, wrussd [rax], r16d
	expect <62h,0E4h,7Fh,08h,0F8h,00h>, enqcmd r16, [rax]
	expect <62h,0FCh,7Eh,08h,0F8h,00h>, enqcmds rax, [r16]
	expect <62h,0E4h,7Dh,08h,0F8h,00h>, movdir64b r16, [rax]
	expect <62h,0FCh,0FCh,08h,0F9h,00h>, movdiri [r16], rax
	expect <62h,0E4h,7Ch,08h,0F9h,00h>, movdiri [rax], r16d
	expect <62h,0FCh,7Ch,08h,0FCh,00h>, aadd [r16], eax
	expect <62h,0E4h,0FDh,08h,0FCh,00h>, aand [rax], r16
	expect <62h,0FCh,0FFh,08h,0FCh,00h>, aor [r16], rax
	expect <62h,0E4h,7Eh,08h,0FCh,08h>, axor [rax], r17d
	expect <62h,0E4h,7Fh,08h,0F8h,0C0h>, urdmsr r16, rax
	expect <62h,0FCh,7Eh,08h,0F8h,0C0h>, uwrmsr rax, r16
	expect <62h,0FFh,7Fh,08h,0F8h,0C0h,01h,00h,00h,00h>, urdmsr r16, 1
	expect <62h,0FFh,7Eh,08h,0F8h,0C4h,05h,00h,00h,00h>, uwrmsr 5, r20
	expect <62h,0D7h,7Fh,08h,0F8h,0C1h,7Bh,00h,00h,00h>, {evex} urdmsr r9, 123
	expect <62h,0D7h,7Eh,08h,0F8h,0C1h,7Bh,00h,00h,00h>, {evex} uwrmsr 123, r9
	expect <62h,0F4h,7Fh,08h,0F8h,0C3h>, {evex} urdmsr rax, rbx
	expect <66h,0Fh,38h,00h,00h>, {evex} pshufb xmm0, [rax]	; SSE is not promoted: {evex} is a preference

	; without APX_F, {evex} (here: "use evex", as for AVX-512 code) leaves
	; legacy instructions alone
	use AMD64, AVX512, MOVBE, ADX, evex
	expect <48h,01h,0D8h>, add rax, rbx
	expect <0F2h,0Fh,38h,0F0h,0C3h>, crc32 eax, bl
	expect <48h,83h,0F8h,01h>, cmp rax, 1
	expect <48h,0Fh,38h,0F0h,03h>, movbe rax, [rbx]
	expect <66h,48h,0Fh,38h,0F6h,0C3h>, adcx rax, rbx
	expect <62h,0F1h,75h,48h,0FEh,0C2h>, vpaddd zmm0, zmm1, zmm2

else if FAIL = 1	; movbe r, r exists only in EVEX
	use i386, x64, MOVBE
	movbe rax, rbx

else if FAIL = 2
	use i386, x64, ADX
	adcx rcx, rax, rbx

else if FAIL = 3
	use i386, x64, USER_MSR
	urdmsr r16, 1

else if FAIL = 4
	use everything
	use32
	movbe eax, ebx

else if FAIL = 5	; adcx/adox have NDD, not NF
	use everything
	adcx {nf} rax, rbx

else if FAIL = 6
	use everything
	movbe al, bl

end if